import sys
class Solution:
    def countGoodNodes(self, edges: list[list[int]]) -> int:
        sys.setrecursionlimit(300000)
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        self.good = 0
        def dfs(u, p):
            sizes = []
            total = 1
            for v in adj[u]:
                if v != p:
                    s = dfs(v, u)
                    sizes.append(s)
                    total += s
            if len(set(sizes)) <= 1:
                self.good += 1
            return total
        dfs(0, -1)
        return self.good

